@router.post("/billing/cards/{card_id}/verify-microdeposit")
@limiter.limit("3/minute")
def verify_card_microdeposits(
    request: Request,
    card_id: str,
    payload: MicrodepositVerification,
    user: User = Depends(get_current_user),
    db: Session = Depends(get_db)
):
    card = db.query(PaymentMethod).filter(
        PaymentMethod.id == card_id,
        PaymentMethod.customer_id == user.customer_id
    ).first()
    if not card:
        raise HTTPException(status_code=404, detail="Payment method not found")

    if card.deposit_amount_1 != payload.amount_1 or card.deposit_amount_2 != payload.amount_2:
        raise HTTPException(status_code=400, detail="Incorrect deposit amounts")

    card.is_verified = True
    db.commit()
    return {"status": "payment_method_verified"}
